#!/usr/bin/env bash
# One-time setup for Codespaces / Dev Containers / local machines.
# Safe to re-run: existing .env files are kept, migrations are additive, demo seed skips if data exists.
set -euo pipefail
cd "$(dirname "$0")/.."

DB_HOST="${DATABASE_HOST:-localhost}"
DB_USER="${DATABASE_USER:-omw}"
DB_PASS="${DATABASE_PASSWORD:-omw_codespace_only}"
secret() { node -e 'console.log(require("crypto").randomBytes(32).toString("hex"))'; }

write_env() { # file db app_env sms
  if [ -f "$1" ]; then echo "• $1 exists — kept as is"; return; fi
  cat > "$1" <<ENV
# Generated by .devcontainer/setup.sh — sandbox/test values only, not production secrets.
APP_ENV=$3
DATABASE_URL="postgresql://${DB_USER}:${DB_PASS}@${DB_HOST}:5432/$2?schema=public"
AUTH_SECRET="$(secret)"
SMS_PROVIDER=$4
PAYMENT_MODE=sandbox
ENV
  echo "• created $1"
}

write_env .env omw_development development sandbox
write_env .env.test omw_test test memory
[ "${SETUP_ONLY_ENV:-0}" = "1" ] && exit 0

echo "• installing dependencies"
npm ci --no-audit --no-fund

echo "• waiting for PostgreSQL at ${DB_HOST}"
for i in $(seq 1 30); do
  if npx prisma migrate deploy >/dev/null 2>&1; then break; fi
  [ "$i" = 30 ] && { echo "PostgreSQL not reachable"; exit 1; }
  sleep 2
done
npx prisma migrate deploy
npx dotenv -e .env.test -o -- npx prisma migrate deploy
npm run demo:seed

cat <<'MSG'

✅ جاهز. التطبيق يعمل على المنفذ 3000 (يفتح تلقائياً).
   الدخول بأي رقم تجريبي (مثلاً 0500000005) — اقرئي الرمز من /dev/sms
   الدليل: docs/TRY_IT.md
MSG
